import{c as a,Q as e,j as s,m as n}from"./chunks/framework.DOi4mjdC.js";const u=JSON.parse('{"title":"Iterate","description":"","frontmatter":{},"headers":[{"level":1,"title":"Iterate","slug":"iterate"},{"level":2,"title":"产品支持情况","slug":"产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"函数原型","slug":"函数原型"},{"level":2,"title":"参数说明","slug":"参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"api/SIMD-API/高阶API/卷积计算/Conv3DBackpropFilter/Conv3DBackpropFilter-Kernel侧接口/Iterate-125.md","filePath":"api/SIMD-API/高阶API/卷积计算/Conv3DBackpropFilter/Conv3DBackpropFilter-Kernel侧接口/Iterate-125.md"}'),l={name:"api/SIMD-API/高阶API/卷积计算/Conv3DBackpropFilter/Conv3DBackpropFilter-Kernel侧接口/Iterate-125.md"};function r(i,t,p,d,o,h){return e(),s("div",null,[...t[0]||(t[0]=[n(`<h1 id="iterate" tabindex="-1">Iterate <a class="header-anchor" href="#iterate" aria-label="Permalink to &quot;Iterate&quot;">​</a></h1><h2 id="产品支持情况" tabindex="-1">产品支持情况 <a class="header-anchor" href="#产品支持情况" aria-label="Permalink to &quot;产品支持情况&quot;">​</a></h2><table tabindex="0"><thead><tr><th>产品</th><th>是否支持</th></tr></thead><tbody><tr><td>Ascend 950PR/Ascend 950DT</td><td>x</td></tr><tr><td>Atlas A3 训练系列产品/Atlas A3 推理系列产品</td><td>√</td></tr><tr><td>Atlas A2 训练系列产品/Atlas A2 推理系列产品</td><td>√</td></tr><tr><td>Atlas 200I/500 A2 推理产品</td><td>x</td></tr><tr><td>Atlas 推理系列产品AI Core</td><td>x</td></tr><tr><td>Atlas 推理系列产品Vector Core</td><td>x</td></tr><tr><td>Atlas 训练系列产品</td><td>x</td></tr></tbody></table><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>每次调用Iterate时，会计算出一个baseM * baseN的结果矩阵，并将该结果写入L0C Buffer。接口内部会维护迭代进度，每次调用后，矩阵的起始地址将进行偏移。如果传入的数据未对齐存在尾块，则在最后一次迭代中输出尾块的计算结果。本接口需与<a href="./GetTensorC-126.html">GetTensorC</a>接口配合使用；在调用本接口后，再调用GetTensorC接口，L0C Buffer中的数据将被写入目标地址。</p><h2 id="函数原型" tabindex="-1">函数原型 <a class="header-anchor" href="#函数原型" aria-label="Permalink to &quot;函数原型&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;bool sync = true&gt;</span></span>
<span class="line"><span>__aicore__ inline bool Iterate(bool enPartialSum = false)</span></span></code></pre></div><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><p><strong>表 1</strong> 模板参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>描述</th></tr></thead><tbody><tr><td>sync</td><td>预留参数，用户无需感知。</td></tr></tbody></table><p><strong>表 2</strong> 接口参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>输入/输出</th><th>描述</th></tr></thead><tbody><tr><td>enPartialSum</td><td>输入</td><td>预留参数，用户无需感知。</td></tr></tbody></table><h2 id="返回值说明" tabindex="-1">返回值说明 <a class="header-anchor" href="#返回值说明" aria-label="Permalink to &quot;返回值说明&quot;">​</a></h2><p>false：设置的SingleShape上的所有数据已经算完。</p><p>true：数据仍在迭代计算中。</p><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><ul><li><p>Iterate接口必须在初始化接口及输入输出配置接口之后进行调用，完成卷积反向实现，调用顺序如下。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Init(...);</span></span>
<span class="line"><span>... // 输入输出配置</span></span>
<span class="line"><span>while (Iterate()) {   </span></span>
<span class="line"><span>    GetTensorC(); </span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>End();</span></span></code></pre></div></li><li><p>在多轮循环计算的场景中，在单次循环里计算单核SetSingleShape设置的数据大小。每次单核计算完成后，必须将Conv3DBackpropFilter对象的ctx.isFirstIter_设置为true，以确保下一轮循环中的单核计算能够正确进行。</p></li></ul><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>while (gradWeight_.Iterate()) {</span></span>
<span class="line"><span>    gradWeight_.GetTensorC(output);</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>// SingleShape计算完成后，需要将ctx.isFirstIter_设置为true，确保下一块SingleShape的正确计算</span></span>
<span class="line"><span>gradWeight_.ctx.isFirstIter_ = true;</span></span></code></pre></div>`,19)])])}const b=a(l,[["render",r]]);export{u as __pageData,b as default};
